create or replace function public.toolbox_issues_state_get(p_workspace_id uuid,p_key text) returns jsonb language sql stable security definer set search_path='' as $$ select case when not private.toolbox_issues_has_access(p_workspace_id) then jsonb_build_object('value',null,'version',0,'data',jsonb_build_object('value',null)) else coalesce((select jsonb_build_object('value',s.value,'version',s.version,'data',jsonb_build_object('value',s.value)) from public.toolbox_issues_state s where s.workspace_id=p_workspace_id and s.key=p_key),jsonb_build_object('value',null,'version',0,'data',jsonb_build_object('value',null))) end $$; create or replace function public.toolbox_issues_state_put(p_workspace_id uuid,p_key text,p_value text,p_previous_version bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare cur bigint; nxt public.toolbox_issues_state%rowtype; begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; select version into cur from public.toolbox_issues_state where workspace_id=p_workspace_id and key=p_key for update; cur:=coalesce(cur,0); if p_previous_version is not null and p_previous_version<>cur then raise exception 'Storage version conflict' using errcode='40001'; end if; insert into public.toolbox_issues_state(workspace_id,key,value,version,updated_by) values(p_workspace_id,p_key,p_value,1,(select auth.uid())) on conflict(workspace_id,key) do update set value=excluded.value,version=public.toolbox_issues_state.version+1,updated_by=excluded.updated_by,updated_at=now() returning * into nxt; return jsonb_build_object('value',nxt.value,'version',nxt.version,'data',jsonb_build_object('value',nxt.value)); end $$; create or replace function public.toolbox_issues_state_delete(p_workspace_id uuid,p_key text) returns jsonb language plpgsql security definer set search_path='' as $$ begin if not private.toolbox_issues_has_access(p_workspace_id) then raise exception 'access denied' using errcode='42501'; end if; delete from public.toolbox_issues_state where workspace_id=p_workspace_id and key=p_key; return jsonb_build_object('success',true); end $$; revoke execute on function public.toolbox_issues_state_get(uuid,text),public.toolbox_issues_state_put(uuid,text,text,bigint),public.toolbox_issues_state_delete(uuid,text) from public,anon; grant execute on function public.toolbox_issues_state_get(uuid,text),public.toolbox_issues_state_put(uuid,text,text,bigint),public.toolbox_issues_state_delete(uuid,text) to authenticated;;
